INSERT INTO tests (code, title, description, created_by) VALUES ('meta_cog_01', 'Опросник «Метакогнитивная включенность в деятельность»', 'Импортировано из docx', 1) ON CONFLICT (code) DO NOTHING;
INSERT INTO test_versions (test_id, version_no, instruction, is_published, created_by) SELECT id, 1, 'Инструкция.', true, 1 FROM tests WHERE code = 'meta_cog_01' ON CONFLICT (test_id, version_no) DO NOTHING;
INSERT INTO questions (version_id, order_num, code, text, question_type, is_required) SELECT id, 1, 'Q_1', '2', 'scale', true FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1 ON CONFLICT (version_id, code) DO NOTHING;
INSERT INTO questions (version_id, order_num, code, text, question_type, is_required) SELECT id, 2, 'Q_2', '3', 'scale', true FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1 ON CONFLICT (version_id, code) DO NOTHING;
INSERT INTO questions (version_id, order_num, code, text, question_type, is_required) SELECT id, 3, 'Q_3', '4', 'scale', true FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1 ON CONFLICT (version_id, code) DO NOTHING;
INSERT INTO questions (version_id, order_num, code, text, question_type, is_required) SELECT id, 4, 'Q_4', '5', 'scale', true FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1 ON CONFLICT (version_id, code) DO NOTHING;
INSERT INTO scales (version_id, code, name, scale_type) SELECT id, 'scale_1', 'Начисление баллов по вопросам производится в зависимости от ответа, данного на тот или иной вопрос. Соответствие ответа количеству баллов следующее', 'sum' FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1 ON CONFLICT (version_id, code) DO NOTHING;
INSERT INTO answer_options (question_id, order_num, text, raw_value) SELECT id, 1, 'Да', 'да' FROM questions WHERE code = 'Q_1' AND version_id = (SELECT id FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1) ON CONFLICT (question_id, order_num) DO NOTHING;
INSERT INTO option_scores (option_id, scale_id, score) SELECT ao.id, s.id, 1 FROM answer_options ao JOIN questions q ON ao.question_id = q.id JOIN scales s ON s.code = 'scale_1' WHERE q.code = 'Q_1' AND ao.order_num = 1 ON CONFLICT (option_id, scale_id) DO NOTHING;
INSERT INTO answer_options (question_id, order_num, text, raw_value) SELECT id, 2, 'Нет', 'нет' FROM questions WHERE code = 'Q_1' AND version_id = (SELECT id FROM test_versions WHERE test_id = (SELECT id FROM tests WHERE code = 'meta_cog_01') AND version_no = 1) ON CONFLICT (question_id, order_num) DO NOTHING;
